   166          if (cp->class) {
   167                  return SEPOL_OK;
   168          }
   169
   170          rc = cil_resolve_name(current, cp->class_str, CIL_SYM_CLASSES, extra_args, &datum);
   171          if (rc != SEPOL_OK) {
   172                  goto exit;
   173          }
   174
   175          class = (struct cil_class *)datum;
   176
   177          if (class->common != NULL) {
